patch.text:
export function parsePulseCommand(text: string): { title: string } | null {
  // Slack messages starting with '/pulse feedback' include the slash as part of the text.
  // Adjust regex to require the slash explicitly at start.
  const match = text.trim().match(/^\/pulse\s+feedback\s+(.+)$/i);
  if (!match) return null;
  const title = match[1].trim();
  if (!title) return null;
  return { title };
}

